"""
Pages Batch 26 (Canvases 161-165, pp. 124-128 / Cxxiiij-Cxxviij) for Wellcome MS.244.
Covers the medical & surgical receipts for Ache and Sciatica on pp. 124-128:
  - Canvas 161 (p. 124 / Cxxiiij): Ache — Black soap & aqua vitae, arm/wrist ache (HD), cat & bitch ointments for sciatica, oil of bays, swallows ointment, Oleum caninum (frogs & oil, Serapion), Ad dolorem Juncturarum, olibanum & aqua vitae, sinews ointment, bruise poultice
  - Canvas 162 (p. 125 / Cxxv): Ache — Herbal oil for ache & bruise, black soap & egg yolk, stone pitch & dragon's blood, pomegranate/resin plaster, nettles & wheat flour, Latin extracts on Tacamahaca & Caranna (Clusius / Monardes), black slate dust (Mr. Helmes), oil of trifolium odoratum, digestive pills
  - Canvas 163 (p. 126): Sciattica — Latin definition & cure (liquid pitch, colocynth, common pills), cross-reference to p. 122, 'ffor the Sciatica a pratise' (making an issue with lapis infernalis/sublimate/acorn/yarrow/ivy), arsesmart (Persicaria) ointments, ground ivy (E. Lucas), deer suet & spices, ox-gall & treacle liniment
  - Canvas 164 (p. 127 / Cxxvij): Sciattica — May broom-flower & butter bladder salve, unwashed butter & balm, Mrs. Busher's sage/rue/marrow ointment, red nettles & cumin plaster, verjuice & elecampane, fenugreek & mustard, black snails & rat's grease, human urine & wool plaster, periwinkle berries, grandmother Eliz. Hungerford's wort-juice plaster, asafoetida & euphorbium cerate
  - Canvas 165 (p. 128 / Cxxviij): Sciattica — Distilled waters (El. & Ny), hog/sow pork & ale distillation, old urine & ox-gall, egg yolks & figs, Latin 'Pro Sciattica' (hermodactyls), white lead & egg oil (p. 54), spearwort/crowfoot blister, tacamahaca/caranna substitutions, 'To kepe open an yssue' (bole armoniac, Burgundy pitch), Monardes plaster, sublimate & gum elemi issue plaster
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


